use vstd::prelude::*;

verus! {

    /// Given a vector of characters `s`, return a new vector containing
    /// the characters in reverse order.
    ///
    /// Ensures:
    ///   1. The result has the same length as `s`.
    ///   2. For every valid index `i`, `result[i] == s[s.len() - 1 - i]`.
    pub fn reverse_string(s: &Vec<char>) -> (result: Vec<char>)
        ensures
            result.len() == s.len(),
        ensures
            forall |i: usize| i < s.len() ==>
                result[i] == s[s.len() - 1 - i],
    {
        // We build up the result one character at a time,
        // pulling from the end of `s` backwards.
        let mut result: Vec<char> = Vec::new();
        // Pre-allocate the required capacity for efficiency.
        result.reserve(s.len());

        let mut i: usize = 0;
        while i < s.len() {
            // Loop invariants:
            // 1. 0 <= i <= s.len()
            // 2. result.len() == i
            // 3. For every j < i, result[j] == s[s.len() - 1 - j]
            invariant  i <= s.len();
            invariant  result.len() == i;
            invariant  forall |j: usize| j < i ==>
                           result[j] == s[s.len() - 1 - j];

            // Pick the character at index `s.len() - 1 - i` and push it.
            let c: char = s[s.len() - 1 - i];
            result.push(c);

            i += 1;
        }

        result
    }
}